function apply(pack,answers){
 // Пакет Крымской войны содержит и ответы российской темы: обновляем все присутствующие зависимости до выбора темы.
 for(const value of Object.values(review))for(const [key,answer] of Object.entries(value.answers))if(Object.hasOwn(answers,key))answers[key]=structuredClone(answer);
 const change=review[pack?.CARD_DATA?.topic?.id];if(!change||!pack.CARD_LEARNING)return;
 for(const [id,value] of Object.entries(change.tasks))pack.CARD_DATA.tasks[id]=structuredClone(value);
 for(const [id,value] of Object.entries(change.items))pack.CARD_DATA.items[id]=structuredClone(value);
 for(const [id,value] of Object.entries(change.learning))pack.CARD_LEARNING[id]=structuredClone(value);
 for(const [id,value] of Object.entries(change.proofs))pack.CARD_PROVENANCE.items[id]=structuredClone(value);
 for(const [key,value] of Object.entries(change.answers)){
  answers[key]=structuredClone(value);
  if(pack.CARD_CATEGORY_ANSWERS[key])Object.assign(pack.CARD_CATEGORY_ANSWERS[key],{text:value.text,question:value.question,title:value.title});
 }
}
window.HISTORY246={version:'V246',tasks:['630A76','6B93A6'],apply};
for(const pack of Object.values(window.CARD_TOPICS||{}))if(pack.CARD_LEARNING)apply(pack,window.CARD_REVIEWED_APPLICATIONS.answers);
